// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.PhotoCameraimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.CircleIconButtonimport com.roshan.persona.ui.components.GlassPanelimport com.roshan.persona.ui.components.StatChipimport com.roshan.persona.ui.state.UiStateProvider/** * Vision screen — camera-based intelligence hub. * * Wired to [UiStateProvider] for device status (battery, thermal). * Camera permission + capture handled by host via [onCapture] callback. * * Modes (passed as List<VisionMode> by host — host knows which engines are ready): *   - OCR · Document · Objects · Faces · Barcode · Screen * * @param modes available vision modes * @param activeMode current selected mode * @param onModeSelected callback when user picks a mode * @param onCapture callback when capture button tapped * @param onFlipCamera callback to flip camera * @param lastResultDescription last captured result (human-readable) * @param stateProvider for battery/thermal display */@Composablefun VisionScreen(    modes: List<VisionMode>,    activeMode: VisionMode,    onModeSelected: (VisionMode) -> Unit,    onCapture: () -> Unit,    onFlipCamera: () -> Unit,    lastResultDescription: String?,    stateProvider: UiStateProvider,    modifier: Modifier = Modifier,) {    val battery by stateProvider.batteryLevel.collectAsState()    val thermal by stateProvider.thermalStatus.collectAsState()    Column(        modifier = modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background),    ) {        // Header        Row(            modifier = Modifier                .fillMaxWidth()                .padding(16.dp),            verticalAlignment = Alignment.CenterVertically,        ) {            Text(                text = "Vision",                style = MaterialTheme.typography.headlineLarge,                fontWeight = FontWeight.Bold,                color = MaterialTheme.colorScheme.onBackground,                modifier = Modifier.weight(1f),            )            StatChip(label = "🔋", value = "$battery%")            Spacer(modifier = Modifier.size(8.dp))            StatChip(label = "🌡", value = thermal)        }        // Mode selector (horizontal scroll)        LazyColumn(            modifier = Modifier.fillMaxWidth(),            verticalArrangement = Arrangement.spacedBy(8.dp),        ) {            item {                Row(                    modifier = Modifier                        .fillMaxWidth()                        .padding(horizontal = 16.dp),                    horizontalArrangement = Arrangement.spacedBy(8.dp),                ) {                    modes.take(3).forEach { mode ->                        ModeChip(                            mode = mode,                            active = mode == activeMode,                            onClick = { onModeSelected(mode) },                        )                    }                }            }            if (modes.size > 3) {                item {                    Row(                        modifier = Modifier                            .fillMaxWidth()                            .padding(horizontal = 16.dp),                        horizontalArrangement = Arrangement.spacedBy(8.dp),                    ) {                        modes.drop(3).forEach { mode ->                            ModeChip(                                mode = mode,                                active = mode == activeMode,                                onClick = { onModeSelected(mode) },                            )                        }                    }                }            }        }        Spacer(modifier = Modifier.size(16.dp))        // Camera preview placeholder        Box(            modifier = Modifier                .fillMaxWidth()                .padding(horizontal = 16.dp)                .size(height = 320.dp, width = 0.dp)                .background(                    color = MaterialTheme.colorScheme.surfaceVariant,                    shape = RoundedCornerShape(24.dp),                ),            contentAlignment = Alignment.Center,        ) {            Column(horizontalAlignment = Alignment.CenterHorizontally) {                Icon(                    imageVector = Icons.Default.PhotoCamera,                    contentDescription = null,                    tint = MaterialTheme.colorScheme.onSurfaceVariant,                    modifier = Modifier.size(64.dp),                )                Spacer(modifier = Modifier.size(8.dp))                Text(                    text = "Camera preview",                    style = MaterialTheme.typography.labelMedium,                    color = MaterialTheme.colorScheme.onSurfaceVariant,                )                Text(                    text = "Mode: ${activeMode.displayName}",                    style = MaterialTheme.typography.labelSmall,                    color = MaterialTheme.colorScheme.onSurfaceVariant,                )            }        }        Spacer(modifier = Modifier.size(16.dp))        // Capture row        Row(            modifier = Modifier                .fillMaxWidth()                .padding(horizontal = 16.dp),            horizontalArrangement = Arrangement.SpaceBetween,            verticalAlignment = Alignment.CenterVertically,        ) {            CircleIconButton(                icon = Icons.Default.PhotoCamera,                contentDescription = "Flip camera",                onClick = onFlipCamera,                size = 48.dp,                gradient = false,            )            CircleIconButton(                icon = Icons.Default.PhotoCamera,                contentDescription = "Capture",                onClick = onCapture,                size = 72.dp,                gradient = true,            )            Box(modifier = Modifier.size(48.dp))        }        Spacer(modifier = Modifier.size(16.dp))        // Last result        if (lastResultDescription != null) {            GlassPanel(                title = "Last Result",                modifier = Modifier.padding(horizontal = 16.dp),            ) {                Text(                    text = lastResultDescription,                    style = MaterialTheme.typography.bodyMedium,                    color = MaterialTheme.colorScheme.onSurface,                )            }        }    }}enum class VisionMode(val displayName: String) {    OCR("OCR"),    Document("Document"),    Objects("Objects"),    Faces("Faces"),    Barcode("Barcode"),    Screen("Screen"),}@Composableprivate fun ModeChip(    mode: VisionMode,    active: Boolean,    onClick: () -> Unit,) {    val bg = if (active) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant    val fg = if (active) androidx.compose.ui.graphics.Color.White else MaterialTheme.colorScheme.onSurfaceVariant    Box(        modifier = Modifier            .background(color = bg, shape = RoundedCornerShape(12.dp))            .clickable(onClick = onClick)            .padding(horizontal = 12.dp, vertical = 8.dp),    ) {        Text(            text = mode.displayName,            style = MaterialTheme.typography.labelMedium,            color = fg,        )    }}